export function listGalleryByStyle(styleId: LuxuryStyleId): readonly PresetGalleryEntry[] {
  return PRESET_GALLERY.filter((entry) => entry.preset.styleId === styleId);
}

export function listGalleryByMaturity(maturity: Maturity): readonly PresetGalleryEntry[] {
  return PRESET_GALLERY.filter((entry) => entry.maturity === maturity);
}

export function listGalleryByPerf(perf: PerfProfile): readonly PresetGalleryEntry[] {
  return PRESET_GALLERY.filter((entry) => entry.preset.perfProfile === perf);
}

export function listGalleryByMotion(level: MotionLevel): readonly PresetGalleryEntry[] {
  return PRESET_GALLERY.filter((entry) => entry.preset.motionLevel === level);
}
